// Hand-written. Not generated by Speakeasy.
//
// The README carries no version number, on purpose.
//
// Its installation block is frozen against regeneration, so any version
// written there would be maintained by hand and would go stale. The repo has
// already carried four at once (0.0.8, 0.0.16, 0.0.18 and a stranded 0.0.17),
// each a string somebody updated in one place and not another. Rather than
// guard a hand edit, the README points at the registry and states none.
//
// Everywhere else the version is generated from .speakeasy/gen.yaml. Those
// have to agree with each other: when they do not, a regeneration was applied
// to some files and reverted in others.
package provider

import (
	"os"
	"regexp"
	"strings"
	"testing"
)

// declaredVersion reads the version the generator works from.
func declaredVersion(t *testing.T) string {
	t.Helper()
	b, err := os.ReadFile("../../.speakeasy/gen.yaml")
	if err != nil {
		t.Fatalf("cannot read gen.yaml: %v", err)
	}
	m := regexp.MustCompile(`(?m)^  version: (\S+)$`).FindSubmatch(b)
	if m == nil {
		t.Fatal("no terraform version in .speakeasy/gen.yaml")
	}
	return string(m[1])
}

// TestREADMEPinsNoVersion keeps the hand-maintained README free of a version
// string, so there is nothing in it to fall out of date.
func TestREADMEPinsNoVersion(t *testing.T) {
	b, err := os.ReadFile("../../README.md")
	if err != nil {
		t.Fatalf("cannot read README.md: %v", err)
	}
	// A commented-out line is guidance, not a pin.
	re := regexp.MustCompile(`(?m)^\s*version\s*=\s*"(\d+\.\d+\.\d+)"`)
	for _, m := range re.FindAllStringSubmatch(string(b), -1) {
		t.Errorf("README.md pins version %s.\n\n"+
			"The installation block is frozen against regeneration, so this "+
			"number is maintained by hand and will go stale. Drop it and let "+
			"the registry page carry the current release.", m[1])
	}
}

// TestGeneratedVersionsAgree catches a regeneration applied to some files and
// reverted in others. That is how docs/index.md ended up holding a stale
// 0.0.18 while the rest of the repo had moved on.
func TestGeneratedVersionsAgree(t *testing.T) {
	want := declaredVersion(t)
	if strings.TrimSpace(want) == "" {
		t.Fatal("gen.yaml declares an empty version")
	}

	generated := map[string]*regexp.Regexp{
		"../sdk/authlete.go":                  regexp.MustCompile(`SDKVersion:\s*"(\d+\.\d+\.\d+)"`),
		"../../examples/provider/provider.tf": regexp.MustCompile(`version\s*=\s*"(\d+\.\d+\.\d+)"`),
		"../../docs/index.md":                 regexp.MustCompile(`version\s*=\s*"(\d+\.\d+\.\d+)"`),
	}
	for path, re := range generated {
		b, err := os.ReadFile(path)
		if err != nil {
			t.Fatalf("cannot read %s: %v", path, err)
		}
		found := re.FindAllStringSubmatch(string(b), -1)
		if len(found) == 0 {
			t.Errorf("%s reports no version. It is generated and should carry %s.", path, want)
			continue
		}
		for _, m := range found {
			if m[1] != want {
				t.Errorf("%s reports version %s while gen.yaml says %s.\n\n"+
					"Both are generated, so disagreeing means a regeneration was "+
					"partly reverted. Regenerate, or revert the rest.", path, m[1], want)
			}
		}
	}
}
